export const buildRs: Excerpt = { file: "build.rs", start: 1, code: "use std::{env, path::PathBuf};\n\nfn main() {\n    if env::var(\"CARGO_CFG_TARGET_OS\").as_deref() != Ok(\"windows\") {\n        panic!(\"Windows x64 is required (D3D12 + Media Foundation + NVIDIA NVDEC)\");\n    }\n    let cuda = PathBuf::from(env::var_os(\"CUDA_PATH\").expect(\"Install the NVIDIA CUDA Toolkit (CUDA_PATH)\"));\n    let sdk = PathBuf::from(env::var_os(\"VIDEO_CODEC_SDK_DIR\").expect(\"Set VIDEO_CODEC_SDK_DIR to the extracted NVIDIA Video Codec SDK\"));\n    let nvcuvid_dir = [sdk.join(\"Lib/win/x64\"), sdk.join(\"Lib/x64\")]\n        .into_iter()\n        .find(|dir| dir.join(\"nvcuvid.lib\").exists())\n        .expect(\"Could not locate SDK nvcuvid.lib (Lib/win/x64 or Lib/x64)\");\n    let headers = sdk.join(\"Interface\");\n    if !headers.join(\"nvcuvid.h\").exists() || !headers.join(\"cuviddec.h\").exists() {\n        panic!(\"Video Codec SDK Interface/nvcuvid.h and cuviddec.h missing\");\n    }\n    println!(\"cargo:rerun-if-changed=native/video_bridge.cu\");\n    println!(\"cargo:rerun-if-changed=native/bitstream.h\");\n    println!(\"cargo:rerun-if-env-changed=VIDEO_CODEC_SDK_DIR\");\n    println!(\"cargo:rerun-if-env-changed=CUDA_PATH\");\n    // \"shared\" links cudart.lib instead of cc's default, cudart_static.lib, which is\n    // built against the static C runtime (LIBCMT) and clashes with Rust's /MD one\n    // (linker warning LNK4098). With CUDA 13, cudart.lib is itself linked statically\n    // and loads the driver's nvcuda.dll at run time, so no CUDA DLL ships with the exe.\n    cc::Build::new()\n        .cuda(true)\n        .cudart(\"shared\")\n        .include(&headers)\n        .include(cuda.join(\"include\"))\n        .file(\"native/video_bridge.cu\")\n        .flag(\"-std=c++17\")\n        .compile(\"video_bridge\");\n    println!(\"cargo:rustc-link-search=native={}\", cuda.join(\"lib/x64\").display());\n    println!(\"cargo:rustc-link-search=native={}\", nvcuvid_dir.display());\n    // cudart itself is linked by cc (see .cudart above)\n    for name in [\"nvcuvid\", \"cuda\", \"d3d12\", \"dxgi\", \"mfplat\", \"mfreadwrite\", \"mfuuid\", \"ole32\"] {\n        println!(\"cargo:rustc-link-lib={name}\");\n    }\n    // CUDA 13's cuda.lib is a static driver-API loader (it opens nvcuda.dll at\n    // run time) built against the static C runtime. Bind it to the same DLL C\n    // runtime as everything else instead of linking a second CRT.\n    println!(\"cargo:rustc-link-arg=/NODEFAULTLIB:LIBCMT\");\n}" };

export const kernel: Excerpt = { file: "native/video_bridge.cu", start: 32, code: "// Simple SDR BT.709 *limited-range* matrix; HDR/P010 and metadata conversion\n// require a different kernel and are rejected in on_sequence for this example.\n__device__ __forceinline__ unsigned char byte_clamp(float v) {\n    return (unsigned char)fminf(255.0f, fmaxf(0.0f, v));\n}\n__global__ void nv12_to_rgba(cudaSurfaceObject_t dst, const uint8_t* nv12,\n                             unsigned pitch, unsigned width, unsigned height) {\n    const unsigned x = blockIdx.x * blockDim.x + threadIdx.x;\n    const unsigned y = blockIdx.y * blockDim.y + threadIdx.y;\n    if (x >= width || y >= height) return;\n    const uint8_t* y_plane = nv12;\n    const uint8_t* uv_plane = nv12 + (size_t)pitch * height;\n    const float Y = (float)y_plane[(size_t)y * pitch + x];\n    const unsigned uv_index = (y / 2) * pitch + (x / 2) * 2;\n    const float U = (float)uv_plane[uv_index] - 128.0f;\n    const float V = (float)uv_plane[uv_index + 1] - 128.0f;\n    const float c = 1.16438356f * (Y - 16.0f);\n    const uchar4 rgba = make_uchar4(\n        byte_clamp(c + 1.79274107f * V),\n        byte_clamp(c - 0.21324861f * U - 0.53290933f * V),\n        byte_clamp(c + 2.11240179f * U), 255);\n    surf2Dwrite(rgba, dst, x * sizeof(uchar4), y);\n}" };

export const startMf: Excerpt = { file: "native/video_bridge.cu", start: 139, code: "HRESULT hr = CoInitializeEx(nullptr, COINIT_MULTITHREADED);\n// winit may already have created an STA on the Windows UI thread.\nif (hr == RPC_E_CHANGED_MODE) hr = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);\nif (FAILED(hr)) return fail(\"CoInitializeEx failed\");\ncom_started = true;\nhr = MFStartup(MF_VERSION);\nif (FAILED(hr)) return fail(\"MFStartup failed\");\nmf_started = true;\nconst std::wstring wide = utf8_to_utf16(path);\nif (wide.empty()) return fail(\"Invalid UTF-8 video path\");\nhr = MFCreateSourceReaderFromURL(wide.c_str(), nullptr, reader.GetAddressOf());\nif (FAILED(hr)) return fail(\"MFCreateSourceReaderFromURL failed (MP4 file required)\");" };

export const openReader: Excerpt = { file: "native/video_bridge.cu", start: 151, code: "// Disable all other tracks; preserve the *native compressed* video type.\nhr = reader->SetStreamSelection(kAllStreams, FALSE);\nif (FAILED(hr)) return fail(\"Disable other streams failed\");\nhr = reader->SetStreamSelection(kVideoStream, TRUE);\nif (FAILED(hr)) return fail(\"Select video stream failed\");\nhr = reader->GetNativeMediaType(kVideoStream, 0, compressed_type.GetAddressOf());\nif (FAILED(hr)) return fail(\"Cannot get native compressed video type\");\nGUID subtype = {};\nif (FAILED(compressed_type->GetGUID(MF_MT_SUBTYPE, &subtype))) return fail(\"No video subtype\");\nif (subtype == MFVideoFormat_H264) codec_type = cudaVideoCodec_H264;\nelse if (subtype == MFVideoFormat_HEVC) codec_type = cudaVideoCodec_HEVC;\nelse return fail(\"Only native compressed H.264/HEVC MP4 is supported\");\nhr = reader->SetCurrentMediaType(kVideoStream, nullptr, compressed_type.Get());\nif (FAILED(hr)) return fail(\"Could not keep native compressed video output\");" };

export const sequenceHeader: Excerpt = { file: "native/video_bridge.cu", start: 165, code: "if (FAILED(MFGetAttributeSize(compressed_type.Get(), MF_MT_FRAME_SIZE, &width, &height)) ||\n    !width || !height || (width & 1) || (height & 1)) {\n    return fail(\"Missing/unsupported video frame size (even dimensions required)\");\n}\nUINT32 header_size = 0;\nif (SUCCEEDED(compressed_type->GetBlobSize(MF_MT_MPEG_SEQUENCE_HEADER, &header_size)) && header_size) {\n    sequence_header.resize(header_size);\n    UINT32 got = 0;\n    if (FAILED(compressed_type->GetBlob(MF_MT_MPEG_SEQUENCE_HEADER,\n            sequence_header.data(), header_size, &got))) return fail(\"Sequence-header read failed\");\n    sequence_header.resize(got);\n    // MF sequence headers are Annex B SPS/PPS or VPS/SPS/PPS, NOT avcC/hvcC.\n    if (!annexb_prefix(sequence_header.data(), sequence_header.size()))\n        return fail(\"Expected Annex B MF_MT_MPEG_SEQUENCE_HEADER\");\n}" };

export const luid: Excerpt = { file: "native/video_bridge.cu", start: 186, code: "bool init_cuda(ID3D12Device* dev) {\n    if (!dev) return fail(\"Missing wgpu D3D12 device\");\n    d3d = dev;\n    if (!check(cuInit(0), \"cuInit\")) return false;\n    int count = 0;\n    if (!check(cuDeviceGetCount(&count), \"cuDeviceGetCount\")) return false;\n    const LUID adapter_luid = dev->GetAdapterLuid();\n    CUdevice match = -1;\n    for (int i = 0; i < count; ++i) {\n        CUdevice candidate = 0;\n        char cuda_luid[8] = {};\n        unsigned node_mask = 0;\n        if (cuDeviceGet(&candidate, i) == CUDA_SUCCESS &&\n            cuDeviceGetLuid(cuda_luid, &node_mask, candidate) == CUDA_SUCCESS &&\n            std::memcmp(cuda_luid, &adapter_luid, sizeof(cuda_luid)) == 0) {\n            match = candidate;\n            break;\n        }\n    }\n    if (match < 0) return fail(\"CUDA device LUID doesn't match the wgpu D3D12 NVIDIA adapter\");\n    if (!check(cuCtxCreate(\n        &cuda_context,\n        nullptr,\n        0,\n        match\n    ), \"cuCtxCreate\")) return false;\n    // cuCtxCreate makes this context current; pop so every call explicitly pushes it.\n    pop();" };

export const createResource: Excerpt = { file: "native/video_bridge.cu", start: 216, code: "for (auto& slot : slots) {\n    D3D12_HEAP_PROPERTIES heap = {};\n    heap.Type = D3D12_HEAP_TYPE_DEFAULT;\n    D3D12_RESOURCE_DESC desc = {};\n    desc.Dimension = D3D12_RESOURCE_DIMENSION_TEXTURE2D;\n    desc.Width = width;\n    desc.Height = height;\n    desc.DepthOrArraySize = 1;\n    desc.MipLevels = 1;\n    desc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;\n    desc.SampleDesc.Count = 1;\n    desc.Layout = D3D12_TEXTURE_LAYOUT_UNKNOWN;\n    desc.Flags = D3D12_RESOURCE_FLAG_ALLOW_SIMULTANEOUS_ACCESS;\n    HRESULT hr = dev->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_SHARED, &desc,\n        D3D12_RESOURCE_STATE_COMMON, nullptr, IID_PPV_ARGS(&slot.texture));\n    if (FAILED(hr)) { ok = fail(\"CreateCommittedResource failed\"); break; }\n    HANDLE shared = nullptr;\n    hr = dev->CreateSharedHandle(slot.texture.Get(), nullptr, GENERIC_ALL, nullptr, &shared);\n    if (FAILED(hr)) { ok = fail(\"CreateSharedHandle failed\"); break; }" };

export const importToCuda: Excerpt = { file: "native/video_bridge.cu", start: 235, code: "cudaExternalMemoryHandleDesc memory_desc = {};\nmemory_desc.type = cudaExternalMemoryHandleTypeD3D12Resource;\nmemory_desc.handle.win32.handle = shared;\nmemory_desc.size = dev->GetResourceAllocationInfo(0, 1, &desc).SizeInBytes;\nmemory_desc.flags = cudaExternalMemoryDedicated;\nconst cudaError_t imported = cudaImportExternalMemory(&slot.memory, &memory_desc);\nCloseHandle(shared);\nif (!check_cuda(imported, \"cudaImportExternalMemory\")) { ok = false; break; }\ncudaExternalMemoryMipmappedArrayDesc mapping = {};\nmapping.offset = 0;\nmapping.formatDesc = cudaCreateChannelDesc(8, 8, 8, 8, cudaChannelFormatKindUnsigned);\nmapping.extent = make_cudaExtent(width, height, 1);\nmapping.flags = cudaArraySurfaceLoadStore;\nmapping.numLevels = 1;\nif (!check_cuda(cudaExternalMemoryGetMappedMipmappedArray(&slot.mipmap, slot.memory, &mapping),\n                \"cudaExternalMemoryGetMappedMipmappedArray\")) { ok = false; break; }\ncudaArray_t array = nullptr;\nif (!check_cuda(cudaGetMipmappedArrayLevel(&array, slot.mipmap, 0),\n                \"cudaGetMipmappedArrayLevel\")) { ok = false; break; }\ncudaResourceDesc resource = {};\nresource.resType = cudaResourceTypeArray;\nresource.res.array.array = array;\nif (!check_cuda(cudaCreateSurfaceObject(&slot.surface, &resource),\n                \"cudaCreateSurfaceObject\")) { ok = false; break; }" };

export const callbacks: Excerpt = { file: "native/video_bridge.cu", start: 264, code: "static int CUDAAPI sequence_cb(void* user, CUVIDEOFORMAT* fmt) {\n    return static_cast<Bridge*>(user)->on_sequence(fmt);\n}\nstatic int CUDAAPI decode_cb(void* user, CUVIDPICPARAMS* pic) {\n    auto* b = static_cast<Bridge*>(user);\n    return b->decoder && b->check(cuvidDecodePicture(b->decoder, pic), \"cuvidDecodePicture\") ? 1 : 0;\n}\nstatic int CUDAAPI display_cb(void* user, CUVIDPARSERDISPINFO* info) {\n    auto* b = static_cast<Bridge*>(user);\n    if (!info) return 1;\n    if (b->decoded.size() >= 64) { b->fail(\"Decoder display queue overflow\"); return 0; }\n    b->decoded.push_back(*info); // Parser delivers display/reordered order.\n    return 1;\n}" };

export const formatChecks: Excerpt = { file: "native/video_bridge.cu", start: 278, code: "int on_sequence(CUVIDEOFORMAT* f) {\n    if (!f || f->codec != codec_type || f->chroma_format != cudaVideoChromaFormat_420 ||\n        f->bit_depth_luma_minus8 != 0 || !f->progressive_sequence) {\n        fail(\"Only progressive 8-bit 4:2:0 video is supported (NV12)\"); return 0;\n    }\n    if (decoder) {\n        if (decode_width != f->coded_width || decode_height != f->coded_height) {\n            fail(\"Midstream resolution changes are not supported\"); return 0;\n        }\n        return std::max(\n            2u,\n            static_cast<unsigned int>(f->min_num_decode_surfaces)\n        );\n    }" };

export const createDecoder: Excerpt = { file: "native/video_bridge.cu", start: 292, code: "CUVIDDECODECAPS caps = {};\ncaps.eCodecType = f->codec;\ncaps.eChromaFormat = f->chroma_format;\ncaps.nBitDepthMinus8 = f->bit_depth_luma_minus8;\nif (!check(cuvidGetDecoderCaps(&caps), \"cuvidGetDecoderCaps\") || !caps.bIsSupported) {\n    fail(\"Codec/profile not supported by NVIDIA hardware\"); return 0;\n}\ndecode_width = f->coded_width;\ndecode_height = f->coded_height;\nCUVIDDECODECREATEINFO create = {};\ncreate.CodecType = f->codec;\ncreate.ChromaFormat = f->chroma_format;\ncreate.OutputFormat = cudaVideoSurfaceFormat_NV12;\ncreate.DeinterlaceMode = cudaVideoDeinterlaceMode_Weave;\ncreate.ulCreationFlags = cudaVideoCreate_PreferCUVID;\ncreate.ulNumDecodeSurfaces = std::max(\n    2u,\n    static_cast<unsigned int>(f->min_num_decode_surfaces)\n);\ncreate.ulNumOutputSurfaces = 2;\ncreate.ulWidth = f->coded_width;\ncreate.ulHeight = f->coded_height;\ncreate.ulMaxWidth = f->coded_width;\ncreate.ulMaxHeight = f->coded_height;\ncreate.display_area.left = f->display_area.left;\ncreate.display_area.top = f->display_area.top;\ncreate.display_area.right = f->display_area.right;\ncreate.display_area.bottom = f->display_area.bottom;\ncreate.ulTargetWidth = width;\ncreate.ulTargetHeight = height;\nif (!check(cuvidCreateDecoder(&decoder, &create), \"cuvidCreateDecoder\")) return 0;\nreturn (int)create.ulNumDecodeSurfaces;" };

export const createParser: Excerpt = { file: "native/video_bridge.cu", start: 325, code: "bool create_parser() {\n    if (parser) { if (!check(cuvidDestroyVideoParser(parser), \"cuvidDestroyVideoParser\")) return false; parser = nullptr; }\n    if (decoder) { if (!check(cuvidDestroyDecoder(decoder), \"cuvidDestroyDecoder\")) return false; decoder = nullptr; }\n    decode_width = 0; decode_height = 0;\n    CUVIDPARSERPARAMS parameters = {};\n    parameters.CodecType = codec_type;\n    parameters.ulMaxNumDecodeSurfaces = 20; // Sequence callback can override.\n    parameters.ulMaxDisplayDelay = 2; // Frames the parser may hold before the display callback (0 = none).\n    parameters.pUserData = this;\n    parameters.pfnSequenceCallback = &Bridge::sequence_cb;\n    parameters.pfnDecodePicture = &Bridge::decode_cb;\n    parameters.pfnDisplayPicture = &Bridge::display_cb;\n    if (!check(cuvidCreateVideoParser(&parser, &parameters), \"cuvidCreateVideoParser\")) return false;\n    if (!sequence_header.empty()) {\n        CUVIDSOURCEDATAPACKET pkt = {};\n        pkt.payload = sequence_header.data();\n        pkt.payload_size = (unsigned long)sequence_header.size();\n        if (!check(cuvidParseVideoData(parser, &pkt), \"cuvidParseVideoData(sequence header)\")) return false;\n    }\n    return true;\n}" };

export const readPacket: Excerpt = { file: "native/video_bridge.cu", start: 369, code: "bool read_packet() {\n    DWORD flags = 0;\n    LONGLONG timestamp = 0;\n    ComPtr<IMFSample> sample;\n    const HRESULT hr = reader->ReadSample(kVideoStream, 0,\n        nullptr, &flags, &timestamp, sample.GetAddressOf());\n    if (FAILED(hr)) return fail(\"IMFSourceReader::ReadSample failed\");\n    if (flags & (MF_SOURCE_READERF_NATIVEMEDIATYPECHANGED | MF_SOURCE_READERF_CURRENTMEDIATYPECHANGED))\n        return fail(\"Dynamic compressed media-type changes unsupported\");\n    if (flags & MF_SOURCE_READERF_ENDOFSTREAM) { has_eos = true; return true; }\n    if (!sample) return true; // stream tick / no sample\n    ComPtr<IMFMediaBuffer> buf;\n    if (FAILED(sample->ConvertToContiguousBuffer(buf.GetAddressOf()))) return fail(\"Cannot obtain compressed sample\");\n    BYTE* bytes = nullptr;\n    DWORD count = 0;\n    if (FAILED(buf->Lock(&bytes, nullptr, &count))) return fail(\"Compressed packet Lock failed\");" };

export const normalizePacket: Excerpt = { file: "native/video_bridge.cu", start: 385, code: "// MF's MPEG-4 source typically presents Annex B, but handle MP4 length-prefixed packets too.\n// The first sample decides which; every later sample must match it.\nconst NalFraming before = framing;\nconst bool converted = annexb_sample(bytes, count, bitstream, framing);\nbuf->Unlock();\nif (!converted) {\n    return fail(before == NalFraming::AnnexB ? \"Invalid compressed NAL units (stream started as Annex B)\"\n        : before == NalFraming::LengthPrefixed ? \"Invalid compressed NAL units (stream started with four-byte lengths)\"\n        : \"Invalid compressed NAL units (expected Annex B or four-byte lengths)\");\n}\nif (before == NalFraming::Unknown) {\n    std::printf(\"[mf] NAL framing: %s\\n\", framing == NalFraming::AnnexB ? \"Annex B\" : \"four-byte lengths\");\n    std::fflush(stdout);\n}\nif (bitstream.size() > UINT32_MAX) return fail(\"Compressed packet too large\");\nCUVIDSOURCEDATAPACKET pkt = {};\npkt.flags = CUVID_PKT_TIMESTAMP;\npkt.timestamp = timestamp; // MF sample time and CUVID timestamps both use 100ns ticks.\npkt.payload = bitstream.data();\npkt.payload_size = (unsigned long)bitstream.size();\nif (!push()) return false;\nconst bool ok = check(cuvidParseVideoData(parser, &pkt), \"cuvidParseVideoData(packet)\");\npop();\nreturn ok;" };

export const feedLoop: Excerpt = { file: "native/video_bridge.cu", start: 410, code: "// Return 1 on success, -1 on error. out_pts: presentation time in 100ns units.\nint next(int* out_slot, int64_t* out_pts) {\n    if (!out_slot || !out_pts) { fail(\"Null frame result\"); return -1; }\n    // Read compressed packets only until a display-order frame becomes available.\n    // Consume that frame before submitting additional packets: protects NVDEC output surfaces.\n    for (unsigned steps = 0; decoded.empty(); ++steps) {\n        if (steps > 100000) { fail(\"No decodable video frames\"); return -1; }\n        if (!has_eos) {\n            if (!read_packet()) return -1;\n        } else if (!flushed) {\n            CUVIDSOURCEDATAPACKET eos = {};\n            eos.flags = CUVID_PKT_ENDOFSTREAM;\n            if (!push()) return -1;\n            bool ok = check(cuvidParseVideoData(parser, &eos), \"cuvidParseVideoData(EOS)\");\n            pop();\n            if (!ok) return -1;\n            flushed = true;\n        } else {\n            if (!rewind_video()) return -1;\n        }\n    }" };

export const mapFrame: Excerpt = { file: "native/video_bridge.cu", start: 431, code: "CUVIDPARSERDISPINFO display = decoded.front();\ndecoded.pop_front();\nconst int slot_index = (current_slot + 1) % kSlots;\nif (!push()) return -1;\nCUVIDPROCPARAMS process = {};\nprocess.progressive_frame = display.progressive_frame;\nprocess.top_field_first = display.top_field_first;\nprocess.second_field = 0;\nprocess.unpaired_field = display.repeat_first_field < 0;\nCUdeviceptr device_frame = 0;\nunsigned pitch = 0;\nbool ok = check(cuvidMapVideoFrame(decoder, display.picture_index,\n    &device_frame, &pitch, &process), \"cuvidMapVideoFrame\");" };

export const convertFrame: Excerpt = { file: "native/video_bridge.cu", start: 444, code: "if (ok) {\n    const dim3 threads(16, 16);\n    const dim3 blocks((width + 15) / 16, (height + 15) / 16);\n    nv12_to_rgba<<<blocks, threads>>>(slots[slot_index].surface,\n        reinterpret_cast<const uint8_t*>(device_frame), pitch, width, height);\n    ok = check_cuda(cudaGetLastError(), \"CUDA color-convert launch\") &&\n         check_cuda(cudaDeviceSynchronize(), \"CUDA color-convert synchronize\");\n    // Unmap only once the CUDA kernel has finished accessing NVDEC memory.\n    const bool unmapped = check(cuvidUnmapVideoFrame(decoder, device_frame), \"cuvidUnmapVideoFrame\");\n    ok = unmapped && ok;\n}\npop();\nif (!ok) return -1;\ncurrent_slot = slot_index;\nif (first_timestamp < 0) first_timestamp = display.timestamp;\nlast_pts = std::max<int64_t>(0, display.timestamp - first_timestamp);\n*out_slot = slot_index;\n*out_pts = last_pts;\nreturn 1;" };

export const cAbi: Excerpt = { file: "native/video_bridge.cu", start: 466, code: "extern \"C\" {\n__declspec(dllexport) Bridge* nv_open(const char* path, void* d3d_device) {\n    std::unique_ptr<Bridge> bridge(new (std::nothrow) Bridge());\n    if (!bridge || !bridge->init(path, reinterpret_cast<ID3D12Device*>(d3d_device))) return nullptr;\n    return bridge.release();\n}\n__declspec(dllexport) int nv_width(Bridge* b) { return b ? (int)b->width : 0; }\n__declspec(dllexport) int nv_height(Bridge* b) { return b ? (int)b->height : 0; }\n__declspec(dllexport) void* nv_texture(Bridge* b, int index) {\n    if (!b || index < 0 || index >= kSlots) return nullptr;\n    ID3D12Resource* texture = b->slots[index].texture.Get();\n    if (texture) texture->AddRef(); // Rust from_raw takes this additional reference.\n    return texture;\n}\n__declspec(dllexport) int nv_next(Bridge* b, int* slot, int64_t* pts) {\n    return b ? b->next(slot, pts) : -1;\n}\n__declspec(dllexport) const char* nv_error(Bridge* b) { return b ? b->error.c_str() : \"No video bridge\"; }\n__declspec(dllexport) void nv_close(Bridge* b) { delete b; }\n}" };

export const framing: Excerpt = { file: "native/bitstream.h", start: 23, code: "// True when nal_len_bytes-byte lengths tile the whole sample exactly, every\n// NAL unit is non-empty, and every NAL header has its forbidden_zero_bit (the\n// top bit, in both H.264 and HEVC) clear.\ninline bool length_prefixed(const uint8_t* p, size_t n, unsigned nal_len_bytes) {\n    if (!n || !(nal_len_bytes == 1 || nal_len_bytes == 2 || nal_len_bytes == 4)) return false;\n    while (n) {\n        if (n < nal_len_bytes) return false;\n        size_t count = 0;\n        for (unsigned i = 0; i < nal_len_bytes; ++i) count = (count << 8) | p[i];\n        p += nal_len_bytes;\n        n -= nal_len_bytes;\n        if (count == 0 || count > n || (p[0] & 0x80)) return false;\n        p += count;\n        n -= count;\n    }\n    return true;\n}\n\n// Which framing one sample uses. The length check wins: a 4-byte length of 1\n// or 256-511 starts with 00 00 00 01 / 00 00 01 xx, which looks exactly like a\n// start code, while real Annex B data practically never tiles as lengths.\ninline NalFraming detect_framing(const uint8_t* p, size_t n, unsigned nal_len_bytes = 4) {\n    if (length_prefixed(p, n, nal_len_bytes)) return NalFraming::LengthPrefixed;\n    if (annexb_prefix(p, n)) return NalFraming::AnnexB;\n    return NalFraming::Unknown;\n}" };

