export const openBridge: Excerpt = { file: "src/video.rs", start: 54, code: "pub fn open(device: &wgpu::Device, filename: &str) -> Result<Self, String> {\n    let hal = unsafe { device.as_hal::<wgpu::hal::api::Dx12>() }\n        .ok_or(\"wgpu must use the D3D12 backend\")?;\n    let file = CString::new(filename).map_err(|e| e.to_string())?;\n    let native = NonNull::new(unsafe { nv_open(file.as_ptr(), hal.raw_device().as_raw()) })\n        .ok_or(\"Media Foundation / Video Codec SDK initialization failed (see stderr)\")?;\n    // Decode initial + lookahead frame before importing the D3D12 resources into wgpu.\n    // On failure, always release the native decoder and CUDA resources.\n    let result = (|| {\n        let width = unsafe { nv_width(native.as_ptr()) } as u32;\n        let height = unsafe { nv_height(native.as_ptr()) } as u32;\n        if width == 0 || height == 0 { return Err(\"Invalid video dimensions\".to_owned()); }\n        let current = Self::decode(native)?;\n        let pending = Self::decode(native)?;" };

export const wrapTextures: Excerpt = { file: "src/video.rs", start: 69, code: "for slot in 0..SLOTS {\n    let resource_ptr = unsafe { nv_texture(native.as_ptr(), slot as i32) };\n    if resource_ptr.is_null() { return Err(format!(\"D3D12 resource slot {slot} missing\")); }\n    // C++ AddRef's, Rust from_raw takes ownership of the additional COM reference.\n    let resource = unsafe { ID3D12Resource::from_raw(resource_ptr) };\n    let desc = wgpu::TextureDescriptor {\n        label: Some(\"Video Codec SDK CUDA-shared RGBA texture\"),\n        size: wgpu::Extent3d { width, height, depth_or_array_layers: 1 },\n        mip_level_count: 1,\n        sample_count: 1,\n        dimension: wgpu::TextureDimension::D2,\n        format: wgpu::TextureFormat::Rgba8Unorm,\n        usage: wgpu::TextureUsages::TEXTURE_BINDING,\n        view_formats: &[],\n    };\n    let wrapped = unsafe {\n        wgpu::hal::dx12::Device::texture_from_raw(\n            resource,\n            desc.format,\n            desc.dimension,\n            desc.size,\n            desc.mip_level_count,\n            desc.sample_count,\n        )\n    };\n    let tex = unsafe { device.create_texture_from_hal::<wgpu::hal::api::Dx12>(\n        wrapped, &desc, wgpu::TextureUses::RESOURCE) };\n    textures.push(tex);\n}" };

