export const background: Excerpt = { file: "src/main.rs", start: 42, code: "/// The window background, rgb(69, 80, 93), as clear values for `format`. Clear colors are\n/// linear on sRGB targets, so the display value is decoded there.\nfn background(format: wgpu::TextureFormat) -> wgpu::Color {\n    let [r, g, b] = [69.0, 80.0, 93.0].map(|v: f64| {\n        let c = v / 255.0;\n        if !format.is_srgb() { c } else if c <= 0.04045 { c / 12.92 } else { ((c + 0.055) / 1.055).powf(2.4) }\n    });\n    wgpu::Color { r, g, b, a: 1.0 }\n}" };

