export const bridgeIncludes: Excerpt = { file: "native/video_bridge.cu", start: 1, code: "// Windows/x64 only. No FFmpeg: Media Foundation provides *compressed* packets;\n// NVIDIA Video Codec SDK (nvcuvid) parses/decodes; CUDA writes D3D12 textures.\n#define NOMINMAX\n#define WIN32_LEAN_AND_MEAN\n#include <windows.h>\n#include <mfapi.h>\n#include <mfidl.h>\n#include <mfreadwrite.h>\n#include <wrl/client.h>\n#include <d3d12.h>\n#include <cuda.h>\n#include <cuda_runtime.h>\n#include <nvcuvid.h>\n#include <algorithm>\n#include <array>\n#include <cstdint>\n#include <cstdio>\n#include <cstring>\n#include <deque>\n#include <memory>\n#include <new>\n#include <string>\n#include <vector>\n#include \"bitstream.h\"\n\nusing Microsoft::WRL::ComPtr;\nstatic constexpr int kSlots = 3;\n// The Source Reader's stream selectors are negative enum values passed as DWORD.\nstatic constexpr DWORD kVideoStream = static_cast<DWORD>(MF_SOURCE_READER_FIRST_VIDEO_STREAM);\nstatic constexpr DWORD kAllStreams = static_cast<DWORD>(MF_SOURCE_READER_ALL_STREAMS);" };

