export const helpers: Excerpt = { file: "native/video_bridge.cu", start: 100, code: "bool fail(const char* message) {\n    if (error.empty()) error = message;\n    std::fprintf(stderr, \"[nvdec] %s\\n\", message);\n    return false;\n}\nbool check(CUresult result, const char* message) {\n    if (result == CUDA_SUCCESS) return true;\n    const char* name = \"unknown\";\n    cuGetErrorName(result, &name);\n    error = std::string(message) + \": \" + (name ? name : \"unknown\");\n    std::fprintf(stderr, \"[nvdec] %s\\n\", error.c_str());\n    return false;\n}\nbool check_cuda(cudaError_t result, const char* message) {\n    if (result == cudaSuccess) return true;\n    error = std::string(message) + \": \" + cudaGetErrorString(result);\n    std::fprintf(stderr, \"[nvdec] %s\\n\", error.c_str());\n    return false;\n}\nbool push() { return check(cuCtxPushCurrent(cuda_context), \"cuCtxPushCurrent\"); }\nvoid pop() { CUcontext old = nullptr; cuCtxPopCurrent(&old); }" };

export const destructor: Excerpt = { file: "native/video_bridge.cu", start: 122, code: "~Bridge() {\n    // Caller must release every wrapped wgpu texture before nv_close!\n    if (cuda_context && push()) {\n        if (parser) cuvidDestroyVideoParser(parser);\n        if (decoder) cuvidDestroyDecoder(decoder);\n        for (auto& slot : slots) slot.cleanup();\n        pop();\n        cuCtxDestroy(cuda_context);\n    }\n    reader.Reset();\n    compressed_type.Reset();\n    d3d.Reset();\n    if (mf_started) MFShutdown();\n    if (com_started) CoUninitialize();\n}" };

