export const startCode: Excerpt = { file: "native/bitstream.h", start: 1, code: "#pragma once\n#include <cstddef>\n#include <cstdint>\n#include <vector>\n\n// How a stream's samples separate NAL units: Annex B start codes, or the MP4\n// length prefixes (avcC/hvcC style). One track uses one framing throughout.\nenum class NalFraming { Unknown, AnnexB, LengthPrefixed };\n\n// Bytes taken by a start code at p (00 00 01, or more zeros then 01), 0 if none.\ninline size_t start_code_length(const uint8_t* p, size_t n) {\n    size_t zeros = 0;\n    while (zeros < n && p[zeros] == 0) ++zeros;\n    return zeros >= 2 && zeros < n && p[zeros] == 1 ? zeros + 1 : 0;\n}\n\n// A start code followed by at least one byte of NAL unit.\ninline bool annexb_prefix(const uint8_t* p, size_t n) {\n    const size_t prefix = start_code_length(p, n);\n    return prefix && prefix < n;\n}" };

export const normalize: Excerpt = { file: "native/bitstream.h", start: 50, code: "// Normalizes one sample to Annex B in out. With framing Unknown, it's detected\n// from this sample and stored, so the caller keeps it for the rest of the\n// stream; after that, every sample must parse in that framing. Malformed input\n// is rejected rather than guessed at.\ninline bool annexb_sample(const uint8_t* p, size_t n, std::vector<uint8_t>& out,\n                          NalFraming& framing, unsigned nal_len_bytes = 4) {\n    out.clear();\n    if (!n) return false;\n    const NalFraming kind = framing == NalFraming::Unknown ? detect_framing(p, n, nal_len_bytes) : framing;\n    if (kind == NalFraming::AnnexB) {\n        if (!annexb_prefix(p, n)) return false;\n        out.assign(p, p + n);\n    } else if (kind == NalFraming::LengthPrefixed) {\n        if (!length_prefixed(p, n, nal_len_bytes)) return false;\n        while (n) {\n            size_t count = 0;\n            for (unsigned i = 0; i < nal_len_bytes; ++i) count = (count << 8) | p[i];\n            p += nal_len_bytes;\n            n -= nal_len_bytes;\n            out.insert(out.end(), {0, 0, 0, 1});\n            out.insert(out.end(), p, p + count);\n            p += count;\n            n -= count;\n        }\n    } else {\n        return false;\n    }\n    framing = kind;\n    return true;\n}" };

export const testHelpers: Excerpt = { file: "native/tests/bitstream_test.cpp", start: 1, code: "#include \"../bitstream.h\"\n#include <cassert>\n#include <cstdio>\n\nusing Bytes = std::vector<uint8_t>;\n\n// Converts one sample as the first of a new stream.\nstatic bool convert(const Bytes& in, Bytes& out, unsigned nal_len_bytes = 4) {\n    NalFraming framing = NalFraming::Unknown;\n    return annexb_sample(in.data(), in.size(), out, framing, nal_len_bytes);\n}\n\n// A 4-byte length prefix followed by a NAL unit of `size` bytes (header 0x41).\nstatic Bytes length_nal(size_t size) {\n    Bytes nal = {uint8_t(size >> 24), uint8_t(size >> 16), uint8_t(size >> 8), uint8_t(size), 0x41};\n    for (size_t i = 1; i < size; ++i) nal.push_back(uint8_t(0x10 + i % 0x60));\n    return nal;\n}\n\nstatic Bytes annexb_of(const Bytes& lengths_sample) {\n    Bytes out;\n    size_t i = 0;\n    while (i < lengths_sample.size()) {\n        const size_t count = (size_t(lengths_sample[i]) << 24) | (size_t(lengths_sample[i + 1]) << 16) |\n            (size_t(lengths_sample[i + 2]) << 8) | lengths_sample[i + 3];\n        out.insert(out.end(), {0, 0, 0, 1});\n        out.insert(out.end(), lengths_sample.begin() + i + 4, lengths_sample.begin() + i + 4 + count);\n        i += 4 + count;\n    }\n    return out;\n}" };

export const testCases: Excerpt = { file: "native/tests/bitstream_test.cpp", start: 33, code: "int main() {\n    Bytes out;\n\n    // Annex B passes through unchanged, with 4- and 3-byte start codes.\n    const Bytes annex = {0,0,0,1,0x67,0x64,0,0,0,1,0x68};\n    assert(convert(annex, out) && out == annex);\n    const Bytes annex3 = {0,0,1,0x67,0x64,0,0,1,0x68};\n    assert(convert(annex3, out) && out == annex3);\n\n    // MP4 length prefixes of 4, 2 and 1 bytes become start codes.\n    const Bytes expected = {0,0,0,1,0x67,0x64,0,0,0,1,0x68};\n    assert(convert({0,0,0,2,0x67,0x64,0,0,0,1,0x68}, out) && out == expected);\n    assert(convert({0,2,0x67,0x64,0,1,0x68}, out, 2) && out == expected);\n    assert(convert({2,0x67,0x64,1,0x68}, out, 1) && out == expected);\n\n    // The old misread: 4-byte lengths of 256-511 start 00 00 01 xx and a length\n    // of 1 starts 00 00 00 01, both of which look like start codes.\n    Bytes len300 = length_nal(300);\n    const Bytes tail = length_nal(5);\n    len300.insert(len300.end(), tail.begin(), tail.end());\n    assert(len300[0] == 0 && len300[1] == 0 && len300[2] == 1 && annexb_prefix(len300.data(), len300.size()));\n    assert(convert(len300, out) && out == annexb_of(len300));\n    Bytes len1 = {0,0,0,1,0x09};\n    const Bytes slice = length_nal(40);\n    len1.insert(len1.end(), slice.begin(), slice.end());\n    assert(convert(len1, out) && out == annexb_of(len1));\n\n    // The first sample fixes the framing for the stream.\n    NalFraming framing = NalFraming::Unknown;\n    assert(annexb_sample(annex.data(), annex.size(), out, framing) && framing == NalFraming::AnnexB);\n    assert(annexb_sample(len300.data(), len300.size(), out, framing) && out == len300); // kept as Annex B\n    framing = NalFraming::Unknown;\n    assert(annexb_sample(len1.data(), len1.size(), out, framing) && framing == NalFraming::LengthPrefixed);\n    assert(!annexb_sample(annex.data(), annex.size(), out, framing)); // Annex B can't follow lengths\n    assert(framing == NalFraming::LengthPrefixed);\n\n    // Malformed input is rejected.\n    assert(!convert({0,0,0,20,0x68}, out));           // length past the end\n    assert(!convert({}, out));                         // empty\n    assert(!convert({0,0,0,0}, out));                  // zero length, no start code\n    assert(!convert({0,0,1}, out));                    // start code with no NAL unit\n    assert(!convert({0,0,0,2,0xE7,0x64,0x22}, out));   // tiles, but forbidden_zero_bit set, and no start code\n    assert(!convert({0,0,0,2,0x67,0x64}, out, 3));     // unsupported prefix size\n\n    std::puts(\"bitstream normalization tests passed\");\n}" };

