export const decode: Excerpt = { file: "src/video.rs", start: 40, code: "fn decode(handle: NonNull<VideoHandle>) -> Result<DecodedFrame, String> {\n    let mut slot = -1;\n    let mut pts = -1_i64;\n    if unsafe { nv_next(handle.as_ptr(), &mut slot, &mut pts) } != 1 {\n        let ptr = unsafe { nv_error(handle.as_ptr()) };\n        return Err(if ptr.is_null() { \"Native NVDEC decoder error\".into() }\n            else { unsafe { CStr::from_ptr(ptr) }.to_string_lossy().into_owned() });\n    }\n    if !(0..SLOTS as i32).contains(&slot) {\n        return Err(format!(\"Native NVDEC returned invalid texture slot {slot}\"));\n    }\n    Ok(DecodedFrame { slot: slot as usize, pts_100ns: pts })\n}" };

