export const resize: Excerpt = { file: "src/main.rs", start: 217, code: "fn resize(&mut self, s: winit::dpi::PhysicalSize<u32>) {\n    if s.width == 0 || s.height == 0 { return; }\n    self.config.width = s.width;\n    self.config.height = s.height;\n    self.surface.configure(&self.device, &self.config);\n    self.depth = depth_texture(&self.device, s);\n}" };

export const drawMatrices: Excerpt = { file: "src/main.rs", start: 225, code: "fn draw(&mut self) -> Result<(), Box<dyn std::error::Error>> {\n    // Presentation timestamps determine *when* to advance the video texture.\n    // The cube itself renders at the display refresh cadence.\n    self.video.update(&self.device)?;\n    let elapsed = self.start.elapsed().as_secs_f32();\n    let model = Mat4::from_rotation_y(elapsed * 0.8) * Mat4::from_rotation_x(elapsed * 0.43);\n    let view = Mat4::look_at_rh(Vec3::new(3.2, 2.1, 4.6), Vec3::ZERO, Vec3::Y);\n    let projection = Mat4::perspective_rh(45f32.to_radians(), self.config.width as f32 / self.config.height as f32, 0.1, 100.0);\n    let uniform = Uniform { mvp: (projection * view * model).to_cols_array_2d() };\n    self.queue.write_buffer(&self.uniform, 0, bytemuck::bytes_of(&uniform));" };

export const acquire: Excerpt = { file: "src/main.rs", start: 235, code: "let frame = match self.surface.get_current_texture() {\n    wgpu::CurrentSurfaceTexture::Success(frame)\n    | wgpu::CurrentSurfaceTexture::Suboptimal(frame) => frame,\n\n    wgpu::CurrentSurfaceTexture::Timeout\n    | wgpu::CurrentSurfaceTexture::Occluded => {\n        return Ok(());\n    }\n\n    wgpu::CurrentSurfaceTexture::Outdated => {\n        self.surface.configure(&self.device, &self.config);\n        return Ok(());\n    }\n\n    wgpu::CurrentSurfaceTexture::Lost => {\n        panic!(\"Surface lost; surface recreation required\");\n    }\n\n    wgpu::CurrentSurfaceTexture::Validation => {\n        panic!(\"Surface validation error\");\n    }\n};" };

export const renderPass: Excerpt = { file: "src/main.rs", start: 257, code: "    let output = frame.texture.create_view(&Default::default());\n    let mut encoder = self.device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: Some(\"Cube render\") });\n    {\n        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {\n            label: Some(\"Cube main pass\"),\n            color_attachments: &[Some(wgpu::RenderPassColorAttachment {\n                view: &output, resolve_target: None,\n                ops: wgpu::Operations { load: wgpu::LoadOp::Clear(self.clear), store: wgpu::StoreOp::Store },\n                depth_slice: None,\n            })],\n            depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {\n                view: &self.depth,\n                depth_ops: Some(wgpu::Operations { load: wgpu::LoadOp::Clear(1.0), store: wgpu::StoreOp::Store }),\n                stencil_ops: None,\n            }),\n            occlusion_query_set: None,\n            timestamp_writes: None,\n            multiview_mask: None,\n        });\n        pass.set_pipeline(&self.pipeline);\n        pass.set_bind_group(0, &self.bind_groups[self.video.current_slot()], &[]);\n        pass.set_vertex_buffer(0, self.vertices.slice(..));\n        pass.set_index_buffer(self.indices.slice(..), wgpu::IndexFormat::Uint16);\n        pass.draw_indexed(0..36, 0, 0..1);\n    }\n    self.queue.submit(Some(encoder.finish()));\n    self.window.pre_present_notify();\n    self.queue.present(frame);\n    Ok(())\n}" };

